input.content:
# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""Exclusion categories -> SDG targets/indicators crosswalk.

Subcommands:
  fetch   download the pinned sources into .cache/ and check them against MANIFEST.tsv
  build   write sdg-index.tsv, computed.tsv and gaps.tsv from the pinned sources,
          lexicon.tsv, proposed.tsv and the taxonomy
  verify  rebuild in memory and compare byte-for-byte with the committed files;
          check every span, every proposed quote and every manifest hash

Stdlib only. No clock, host or random value enters any output.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
import urllib.request
import xml.etree.ElementTree as ET
import zipfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
CACHE = HERE / ".cache"
TAXONOMY = HERE.parent.parent / "linked-data" / "taxonomy.json"
UA = "praxis-crosswalk/0.1"
CATEGORY_IRI = "https://ethicic.com/ns/exclusions/category/"
NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

RELATIONS = {"harms", "relates"}
REVIEW_STATUSES = {"proposed", "approved", "rejected"}


# ---------------------------------------------------------------- helpers

def sha256_bytes(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def sha256_text(s: str) -> str:
    return sha256_bytes(s.encode("utf-8"))


def read_tsv(path: Path) -> tuple[list[str], list[str], list[dict[str, str]]]:
    """Return (comment lines, header, rows). Lines starting with '#' are comments."""
    comments: list[str] = []
    header: list[str] | None = None
    rows: list[dict[str, str]] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("#"):
            comments.append(line)
            continue
        if not line.strip():
            continue
        cells = line.split("\t")
        if header is None:
            header = cells
            continue
        if len(cells) != len(header):
            raise SystemExit(f"{path.name}: wrong column count in row: {line[:80]!r}")
        rows.append(dict(zip(header, cells)))
    return comments, header or [], rows


def tsv_bytes(header: list[str], rows: list[list[str]], comments: list[str] = ()) -> bytes:
    out = list(comments) + ["\t".join(header)]
    for r in rows:
        for c in r:
            if "\t" in c or "\n" in c:
                raise SystemExit(f"cell contains tab/newline: {c[:60]!r}")
        out.append("\t".join(r))
    return ("\n".join(out) + "\n").encode("utf-8")


def code_key(code: str) -> tuple:
    """Natural sort key for SDG codes such as 1.a, 12.4, 16.b.1."""
    key = []
    for part in code.split("."):
        key.append((0, int(part), "") if part.isdigit() else (1, 0, part))
    return tuple(key)


# ---------------------------------------------------------------- sources

def manifest() -> dict[str, dict[str, str]]:
    _, _, rows = read_tsv(HERE / "MANIFEST.tsv")
    return {r["name"]: r for r in rows}


def source_path(row: dict[str, str]) -> Path:
    p = row["local_path"]
    return (HERE / p).resolve()


def check_manifest(errors: list[str]) -> None:
    for name, row in manifest().items():
        p = source_path(row)
        if not p.exists():
            errors.append(f"MANIFEST {name}: missing {row['local_path']} (run fetch)")
            continue
        b = p.read_bytes()
        if str(len(b)) != row["bytes"]:
            errors.append(f"MANIFEST {name}: bytes {len(b)} != {row['bytes']}")
        if sha256_bytes(b) != row["sha256"]:
            errors.append(f"MANIFEST {name}: sha256 mismatch")


def cmd_fetch(_: argparse.Namespace) -> int:
    errors: list[str] = []
    for name, row in manifest().items():
        if not row["url"].startswith("http"):
            continue
        p = source_path(row)
        p.parent.mkdir(parents=True, exist_ok=True)
        req = urllib.request.Request(row["url"], headers={"User-Agent": UA})
        with urllib.request.urlopen(req, timeout=60) as r:
            p.write_bytes(r.read())
        print(f"fetched {name} -> {row['local_path']}")
    check_manifest(errors)
    for e in errors:
        print("FAIL", e)
    return 1 if errors else 0


def xlsx_rows(path: Path) -> list[dict[str, str]]:
    z = zipfile.ZipFile(path)
    shared: list[str] = []
    if "xl/sharedStrings.xml" in z.namelist():
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            shared.append("".join(t.text or "" for t in si.iter(f"{{{NS['m']}}}t")))
    sheet = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))
    out = []
    for row in sheet.findall(".//m:row", NS):
        cells: dict[str, str] = {}
        for c in row.findall("m:c", NS):
            col = re.match(r"[A-Z]+", c.get("r", "")).group(0)
            v = c.find("m:v", NS)
            t = c.get("t")
            if t == "s" and v is not None:
                val = shared[int(v.text)]
            elif t == "inlineStr":
                val = "".join(x.text or "" for x in c.iter(f"{{{NS['m']}}}t"))
            else:
                val = v.text if v is not None and v.text else ""
            cells[col] = val
        out.append(cells)
    return out


GOAL_RE = re.compile(r"^Goal (\d{1,2})\.\s+(.*)$", re.S)
TARGET_RE = re.compile(r"^(\d{1,2}\.[0-9a-z]{1,2})\s+(.*)$", re.S)
INDICATOR_RE = re.compile(r"^(\d{1,2}\.[0-9a-z]{1,2}\.\d{1,2})\s+(.*)$", re.S)


def framework() -> tuple[list[dict], list[str]]:
    """Parse the pinned framework xlsx into goal/target/indicator records."""
    src = manifest()["unsd_gif_en_xlsx"]
    records: list[dict] = []
    anomalies: list[str] = []
    target = None
    for cells in xlsx_rows(source_path(src)):
        b = cells.get("B", "").strip()
        c = cells.get("C", "").strip()
        d = cells.get("D", "").strip()
        if (m := GOAL_RE.match(b)):
            records.append({"level": "goal", "code": m.group(1), "unsd": "", "text": m.group(2).strip()})
            target = None
        elif (m := TARGET_RE.match(b)):
            target = m.group(1)
            records.append({"level": "target", "code": target, "unsd": "", "text": m.group(2).strip()})
        elif b:
            anomalies.append(f"unparsed B cell: {b[:70]!r}")
        if c:
            if (m := INDICATOR_RE.match(c)):
                code = m.group(1)
                if target is None or not code.startswith(target + "."):
                    anomalies.append(f"indicator {code} outside target {target}")
                records.append({"level": "indicator", "code": code, "unsd": d, "text": m.group(2).strip()})
            elif c != "Indicators":
                anomalies.append(f"unparsed C cell: {c[:70]!r}")
    return records, anomalies


def skos_uris() -> set[str]:
    src = manifest()["un_library_sdg_skos_ttl"]
    pat = re.compile(r"^<(http://metadata\.un\.org/sdg/[^>]+)> a skos:Concept, ns3:(Goal|Target|Indicator) \.$")
    uris = set()
