# ---------------------------------------------------------------- helpers

def sha256_bytes(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def sha256_text(s: str) -> str:
    return sha256_bytes(s.encode("utf-8"))


def read_tsv(path: Path) -> tuple[list[str], list[str], list[dict[str, str]]]:
    """Return (comment lines, header, rows). Lines starting with '#' are comments."""
    comments: list[str] = []
    header: list[str] | None = None
    rows: list[dict[str, str]] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("#"):
            comments.append(line)
            continue
        if not line.strip():
            continue
        cells = line.split("\t")
        if header is None:
            header = cells
            continue
        if len(cells) != len(header):
            raise SystemExit(f"{path.name}: wrong column count in row: {line[:80]!r}")
        rows.append(dict(zip(header, cells)))
    return comments, header or [], rows


def tsv_bytes(header: list[str], rows: list[list[str]], comments: list[str] = ()) -> bytes:
    out = list(comments) + ["\t".join(header)]
    for r in rows:
        for c in r:
            if "\t" in c or "\n" in c:
                raise SystemExit(f"cell contains tab/newline: {c[:60]!r}")
        out.append("\t".join(r))
    return ("\n".join(out) + "\n").encode("utf-8")


def code_key(code: str) -> tuple:
    """Natural sort key for SDG codes such as 1.a, 12.4, 16.b.1."""
    key = []
    for part in code.split("."):
        key.append((0, int(part), "") if part.isdigit() else (1, 0, part))
    return tuple(key)


