# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""Exclusion categories -> SDG targets/indicators crosswalk.

Subcommands:
  fetch   download the pinned sources into .cache/ and check them against MANIFEST.tsv
  build   write sdg-index.tsv, computed.tsv and gaps.tsv from the pinned sources,
          lexicon.tsv, proposed.tsv and the taxonomy
  verify  rebuild in memory and compare byte-for-byte with the committed files;
          check every span, every proposed quote and every manifest hash

Stdlib only. No clock, host or random value enters any output.
"""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import sys
import urllib.request
import xml.etree.ElementTree as ET
import zipfile
from pathlib import Path

HERE = Path(__file__).resolve().parent
CACHE = HERE / ".cache"
TAXONOMY = HERE.parent.parent / "linked-data" / "taxonomy.json"
UA = "praxis-crosswalk/0.1"
CATEGORY_IRI = "https://ethicic.com/ns/exclusions/category/"
NS = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}

RELATIONS = {"harms", "relates"}
REVIEW_STATUSES = {"proposed", "approved", "rejected"}


# ---------------------------------------------------------------- helpers

def sha256_bytes(b: bytes) -> str:
    return hashlib.sha256(b).hexdigest()


def sha256_text(s: str) -> str:
    return sha256_bytes(s.encode("utf-8"))


def read_tsv(path: Path) -> tuple[list[str], list[str], list[dict[str, str]]]:
    """Return (comment lines, header, rows). Lines starting with '#' are comments."""
    comments: list[str] = []
    header: list[str] | None = None
    rows: list[dict[str, str]] = []
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("#"):
            comments.append(line)
            continue
        if not line.strip():
            continue
        cells = line.split("\t")
        if header is None:
            header = cells
            continue
        if len(cells) != len(header):
            raise SystemExit(f"{path.name}: wrong column count in row: {line[:80]!r}")
        rows.append(dict(zip(header, cells)))
    return comments, header or [], rows


def tsv_bytes(header: list[str], rows: list[list[str]], comments: list[str] = ()) -> bytes:
    out = list(comments) + ["\t".join(header)]
    for r in rows:
        for c in r:
            if "\t" in c or "\n" in c:
                raise SystemExit(f"cell contains tab/newline: {c[:60]!r}")
        out.append("\t".join(r))
    return ("\n".join(out) + "\n").encode("utf-8")


def code_key(code: str) -> tuple:
    """Natural sort key for SDG codes such as 1.a, 12.4, 16.b.1."""
    key = []
    for part in code.split("."):
        key.append((0, int(part), "") if part.isdigit() else (1, 0, part))
    return tuple(key)


# ---------------------------------------------------------------- sources

def manifest() -> dict[str, dict[str, str]]:
    _, _, rows = read_tsv(HERE / "MANIFEST.tsv")
    return {r["name"]: r for r in rows}


def source_path(row: dict[str, str]) -> Path:
    p = row["local_path"]
    return (HERE / p).resolve()


def check_manifest(errors: list[str]) -> None:
    for name, row in manifest().items():
        p = source_path(row)
        if not p.exists():
            errors.append(f"MANIFEST {name}: missing {row['local_path']} (run fetch)")
            continue
        b = p.read_bytes()
        if str(len(b)) != row["bytes"]:
            errors.append(f"MANIFEST {name}: bytes {len(b)} != {row['bytes']}")
        if sha256_bytes(b) != row["sha256"]:
            errors.append(f"MANIFEST {name}: sha256 mismatch")


def cmd_fetch(_: argparse.Namespace) -> int:
    errors: list[str] = []
    for name, row in manifest().items():
        if not row["url"].startswith("http"):
            continue
        p = source_path(row)
        p.parent.mkdir(parents=True, exist_ok=True)
        req = urllib.request.Request(row["url"], headers={"User-Agent": UA})
        with urllib.request.urlopen(req, timeout=60) as r:
            p.write_bytes(r.read())
        print(f"fetched {name} -> {row['local_path']}")
    check_manifest(errors)
    for e in errors:
        print("FAIL", e)
    return 1 if errors else 0


def xlsx_rows(path: Path) -> list[dict[str, str]]:
    z = zipfile.ZipFile(path)
    shared: list[str] = []
    if "xl/sharedStrings.xml" in z.namelist():
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            shared.append("".join(t.text or "" for t in si.iter(f"{{{NS['m']}}}t")))
    sheet = ET.fromstring(z.read("xl/worksheets/sheet1.xml"))
    out = []
    for row in sheet.findall(".//m:row", NS):
        cells: dict[str, str] = {}
        for c in row.findall("m:c", NS):
            col = re.match(r"[A-Z]+", c.get("r", "")).group(0)
            v = c.find("m:v", NS)
            t = c.get("t")
            if t == "s" and v is not None:
                val = shared[int(v.text)]
            elif t == "inlineStr":
                val = "".join(x.text or "" for x in c.iter(f"{{{NS['m']}}}t"))
            else:
                val = v.text if v is not None and v.text else ""
            cells[col] = val
        out.append(cells)
    return out


GOAL_RE = re.compile(r"^Goal (\d{1,2})\.\s+(.*)$", re.S)
TARGET_RE = re.compile(r"^(\d{1,2}\.[0-9a-z]{1,2})\s+(.*)$", re.S)
INDICATOR_RE = re.compile(r"^(\d{1,2}\.[0-9a-z]{1,2}\.\d{1,2})\s+(.*)$", re.S)


def framework() -> tuple[list[dict], list[str]]:
    """Parse the pinned framework xlsx into goal/target/indicator records."""
    src = manifest()["unsd_gif_en_xlsx"]
    records: list[dict] = []
    anomalies: list[str] = []
    target = None
    for cells in xlsx_rows(source_path(src)):
        b = cells.get("B", "").strip()
        c = cells.get("C", "").strip()
        d = cells.get("D", "").strip()
        if (m := GOAL_RE.match(b)):
            records.append({"level": "goal", "code": m.group(1), "unsd": "", "text": m.group(2).strip()})
            target = None
        elif (m := TARGET_RE.match(b)):
            target = m.group(1)
            records.append({"level": "target", "code": target, "unsd": "", "text": m.group(2).strip()})
        elif b:
            anomalies.append(f"unparsed B cell: {b[:70]!r}")
        if c:
            if (m := INDICATOR_RE.match(c)):
                code = m.group(1)
                if target is None or not code.startswith(target + "."):
                    anomalies.append(f"indicator {code} outside target {target}")
                records.append({"level": "indicator", "code": code, "unsd": d, "text": m.group(2).strip()})
            elif c != "Indicators":
                anomalies.append(f"unparsed C cell: {c[:70]!r}")
    return records, anomalies


def skos_uris() -> set[str]:
    src = manifest()["un_library_sdg_skos_ttl"]
    pat = re.compile(r"^<(http://metadata\.un\.org/sdg/[^>]+)> a skos:Concept, ns3:(Goal|Target|Indicator) \.$")
    uris = set()
    for line in source_path(src).read_text(encoding="utf-8").splitlines():
        if (m := pat.match(line)):
            uris.add(m.group(1))
    return uris


def uri_for(rec: dict, uris: set[str]) -> str:
    key = rec["unsd"] if rec["level"] == "indicator" else rec["code"]
    u = f"http://metadata.un.org/sdg/{key}" if key else ""
    return u if u in uris else ""


# ---------------------------------------------------------------- inputs

def taxonomy() -> list[dict]:
    return json.loads(TAXONOMY.read_text(encoding="utf-8"))


def lexicon() -> tuple[list[str], list[dict[str, str]]]:
    comments, header, rows = read_tsv(HERE / "lexicon.tsv")
    if header != ["lexicon_row", "category", "term"]:
        raise SystemExit(f"lexicon.tsv: unexpected header {header}")
    return comments, rows


def proposed() -> list[dict[str, str]]:
    _, header, rows = read_tsv(HERE / "proposed.tsv")
    want = ["category", "sdg_target", "relation", "target_quote", "rationale", "witness", "review_status"]
    if header != want:
        raise SystemExit(f"proposed.tsv: unexpected header {header}")
    return rows


# ---------------------------------------------------------------- matching

SENT_RE = re.compile(r"(?<=[.;])\s+")


def sentences(text: str) -> list[tuple[int, int]]:
    """Split on '.' or ';' followed by whitespace. Returns (start, end) offsets."""
    spans, start = [], 0
    for m in SENT_RE.finditer(text):
        spans.append((start, m.start()))
        start = m.end()
    spans.append((start, len(text)))
    return [(s, e) for s, e in spans if e > s]


def term_regex(term: str) -> re.Pattern:
    return re.compile(r"(?<![A-Za-z0-9])" + re.escape(term) + r"(?![A-Za-z0-9])", re.I)


def compute(records: list[dict], uris: set[str], lex: list[dict[str, str]]) -> list[list[str]]:
    rows = []
    for lr in lex:
        rx = term_regex(lr["term"])
        for rec in records:
            if rec["level"] == "goal":
                continue
            text = rec["text"]
            for s, e in sentences(text):
                if rx.search(text, s, e) is None:
                    continue
                span = text[s:e]
                rows.append([
                    lr["category"], rec["code"], rec["level"], uri_for(rec, uris),
                    lr["term"], lr["lexicon_row"], str(s), str(e), span, sha256_text(span),
                ])
    rows.sort(key=lambda r: (r[0], code_key(r[1]), r[5], int(r[6])))
    return rows


COMPUTED_HEADER = ["category", "sdg_code", "sdg_level", "sdg_uri", "match_term", "lexicon_row",
                   "span_start", "span_end", "span_text", "span_sha256"]
INDEX_HEADER = ["sdg_level", "sdg_code", "unsd_code", "sdg_uri", "text_chars", "text_sha256"]
GAPS_HEADER = ["kind", "subject", "computed_matches", "proposed_targets", "note"]


def build_outputs() -> tuple[dict[str, bytes], list[str]]:
    errors: list[str] = []
    check_manifest(errors)
    if errors:
        return {}, errors
    records, anomalies = framework()
    errors += [f"framework: {a}" for a in anomalies]
    uris = skos_uris()
    lex_comments, lex = lexicon()
    cats = {c["sub_category_code"] for c in taxonomy()}
    for lr in lex:
        if lr["category"] not in cats:
            errors.append(f"lexicon {lr['lexicon_row']}: unknown category {lr['category']}")
    ids = [lr["lexicon_row"] for lr in lex]
    if len(ids) != len(set(ids)):
        errors.append("lexicon: duplicate lexicon_row")

    index_rows = [[r["level"], r["code"], r["unsd"], uri_for(r, uris), str(len(r["text"])), sha256_text(r["text"])]
                  for r in records]
    computed = compute(records, uris, lex)

    prop = proposed()
    targets = {r["code"] for r in records if r["level"] == "target"}
    goals = sorted({r["code"] for r in records if r["level"] == "goal"}, key=int)
    comp_by_cat: dict[str, int] = {}
    for r in computed:
        comp_by_cat[r[0]] = comp_by_cat.get(r[0], 0) + 1
    prop_by_cat: dict[str, set[str]] = {}
    for p in prop:
        prop_by_cat.setdefault(p["category"], set()).add(p["sdg_target"])

    def goal_of(code: str) -> str:
        return code.split(".")[0]

    gaps = []
    for c in sorted(cats):
        nc, np_ = comp_by_cat.get(c, 0), len(prop_by_cat.get(c, ()))
        if nc == 0 and np_ == 0:
            gaps.append(["category_untouched", c, "0", "0", "no computed match and no proposed target"])
        elif nc == 0:
            gaps.append(["category_no_computed", c, "0", str(np_), "no lexicon term occurs in official target or indicator text"])
    goal_comp = {g: 0 for g in goals}
    goal_prop = {g: 0 for g in goals}
    for r in computed:
        goal_comp[goal_of(r[1])] += 1
    for p in prop:
        if goal_of(p["sdg_target"]) in goal_prop:
            goal_prop[goal_of(p["sdg_target"])] += 1
    for g in goals:
        if goal_comp[g] == 0 and goal_prop[g] == 0:
            gaps.append(["goal_untouched", g, "0", "0", "no category has a computed match or proposed target under this goal"])
        elif goal_comp[g] == 0:
            gaps.append(["goal_no_computed", g, "0", str(goal_prop[g]), "touched only by proposals, not by the lexicon"])
    untouched_targets = sorted(targets - {r[1] for r in computed if r[2] == "target"}
                               - {r[1].rsplit(".", 1)[0] for r in computed if r[2] == "indicator"}
                               - {p["sdg_target"] for p in prop}, key=code_key)
    for t in untouched_targets:
        gaps.append(["target_untouched", t, "0", "0", "no computed match on the target or its indicators, and no proposal"])

    out = {
        "sdg-index.tsv": tsv_bytes(INDEX_HEADER, index_rows),
        "computed.tsv": tsv_bytes(COMPUTED_HEADER, computed),
        "gaps.tsv": tsv_bytes(GAPS_HEADER, gaps),
    }
    return out, errors


def check_proposed(errors: list[str]) -> None:
    records, _ = framework()
    text = {r["code"]: r["text"] for r in records if r["level"] == "target"}
    cats = {c["sub_category_code"] for c in taxonomy()}
    seen = set()
    for i, p in enumerate(proposed(), start=2):
        where = f"proposed.tsv row {i} ({p['category']} {p['sdg_target']})"
        if p["category"] not in cats:
            errors.append(f"{where}: unknown category")
        if p["sdg_target"] not in text:
            errors.append(f"{where}: unknown target")
        elif p["target_quote"] not in text[p["sdg_target"]]:
            errors.append(f"{where}: target_quote is not verbatim in the pinned target text")
        if p["relation"] not in RELATIONS:
            errors.append(f"{where}: bad relation {p['relation']!r}")
        if p["review_status"] not in REVIEW_STATUSES:
            errors.append(f"{where}: bad review_status")
        if not p["witness"].startswith("llm:") or "prompt=" not in p["witness"]:
            errors.append(f"{where}: witness must name llm:<model> and prompt=")
        key = (p["category"], p["sdg_target"])
        if key in seen:
            errors.append(f"{where}: duplicate pair")
        seen.add(key)


def check_computed_spans(errors: list[str]) -> None:
    records, _ = framework()
    text = {r["code"]: r["text"] for r in records if r["level"] != "goal"}
    _, _, rows = read_tsv(HERE / "computed.tsv")
    for r in rows:
        s, e = int(r["span_start"]), int(r["span_end"])
        span = text.get(r["sdg_code"], "")[s:e]
        if span != r["span_text"] or sha256_text(span) != r["span_sha256"]:
            errors.append(f"computed {r['category']} {r['sdg_code']}: span does not re-slice")
        if not term_regex(r["match_term"]).search(span):
            errors.append(f"computed {r['category']} {r['sdg_code']}: term not in span")


def cmd_build(_: argparse.Namespace) -> int:
    out, errors = build_outputs()
    for e in errors:
        print("FAIL", e)
    if errors:
        return 1
    for name, b in out.items():
        (HERE / name).write_bytes(b)
        print(f"wrote {name} {len(b)} bytes sha256={sha256_bytes(b)}")
    return 0


def cmd_verify(_: argparse.Namespace) -> int:
    out, errors = build_outputs()
    for name, b in out.items():
        p = HERE / name
        if not p.exists() or p.read_bytes() != b:
            errors.append(f"{name}: committed file differs from rebuild")
    if not errors:
        check_proposed(errors)
        check_computed_spans(errors)
    for e in errors:
        print("FAIL", e)
    if not errors:
        print("verify ok")
    return 1 if errors else 0


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest="cmd", required=True)
    sub.add_parser("fetch").set_defaults(fn=cmd_fetch)
    sub.add_parser("build").set_defaults(fn=cmd_build)
    sub.add_parser("verify").set_defaults(fn=cmd_verify)
    a = ap.parse_args()
    return a.fn(a)


if __name__ == "__main__":
    sys.exit(main())

