def term_regex(term: str) -> re.Pattern:
    return re.compile(r"(?<![A-Za-z0-9])" + re.escape(term) + r"(?![A-Za-z0-9])", re.I)


def compute(records: list[dict], uris: set[str], lex: list[dict[str, str]]) -> list[list[str]]:
    rows = []
    for lr in lex:
        rx = term_regex(lr["term"])
        for rec in records:
            if rec["level"] == "goal":
                continue
            text = rec["text"]
            for s, e in sentences(text):
                if rx.search(text, s, e) is None:
                    continue
                span = text[s:e]
                rows.append([
                    lr["category"], rec["code"], rec["level"], uri_for(rec, uris),
                    lr["term"], lr["lexicon_row"], str(s), str(e), span, sha256_text(span),
                ])
    rows.sort(key=lambda r: (r[0], code_key(r[1]), r[5], int(r[6])))
    return rows


